import{_ as t,o as d,c as a,a2 as i}from"./chunks/framework.CT6jiXWi.js";const u=JSON.parse('{"title":"Programmatic API","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/reference/api.md","filePath":"pipeline/reference/api.md","lastUpdated":1783777611000}'),s={name:"pipeline/reference/api.md"};function n(o,e,r,c,l,h){return d(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="programmatic-api" tabindex="-1">Programmatic API <a class="header-anchor" href="#programmatic-api" aria-label="Permalink to &quot;Programmatic API&quot;">​</a></h1><p>The pipeline engine is a CDS service you connect to and drive from code. This page is the reference for the public <code>DataPipelineService</code> API: registering pipelines, running them, managing schedules and overrides, and registering event hooks.</p><p>The engine itself has <strong>no OData surface</strong> (<code>@protocol: &#39;none&#39;</code>) — for the HTTP management API, see <a href="./management-service.html">Management service</a>. When you use <code>@federation.replicate</code> or <code>@materialize.snapshot</code>, the annotation plugins call <code>addPipeline</code> for you; you only touch this API directly for programmatic pipelines or event hooks.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to &quot;Connecting&quot;">​</a></h2><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> pipelines</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cds.connect.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">to</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;datapipeline&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;DataPipelineService&#39; is an accepted alias</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Connect inside <code>cds.on(&#39;served&#39;, …)</code> in <code>server.js</code>, after the model is loaded.</p><h2 id="addpipeline-config" tabindex="-1"><code>addPipeline(config)</code> <a class="header-anchor" href="#addpipeline-config" aria-label="Permalink to &quot;`addPipeline(config)`&quot;">​</a></h2><p>Registers a pipeline: validates and normalizes the config, initializes its tracker row, starts its schedule (if any), and optionally runs an initial load. Returns once registration is complete (or, with <code>preload.wait</code>, once the initial load finishes).</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipelines.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addPipeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NorthwindProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  source: { service: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;northwind&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, entity: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Products&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  target: { entity: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my.app.LocalProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  mode: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;full&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  schedule: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">600_000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>You do <strong>not</strong> pass a <code>kind</code> — the engine derives the shape (replicate / materialize / move) from the config. See <a href="/cds-data/pipeline/guide/concepts/inference.html">Inference rules</a>.</p><h3 id="top-level-options" tabindex="-1">Top-level options <a class="header-anchor" href="#top-level-options" aria-label="Permalink to &quot;Top-level options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Type / default</th><th>Notes</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code> <strong>(required)</strong></td><td>Unique pipeline id and tracker key.</td></tr><tr><td><code>description</code></td><td><code>string?</code> (max 1024 chars)</td><td>Stored on the tracker; shown in the console.</td></tr><tr><td><code>source</code></td><td><code>object</code> <strong>(required)</strong></td><td>Read side — see <a href="#source"><code>source</code></a>.</td></tr><tr><td><code>target</code></td><td><code>object</code> <strong>(required)</strong></td><td>Write side — see <a href="#target"><code>target</code></a>.</td></tr><tr><td><code>mode</code></td><td><code>&#39;delta&#39; | &#39;full&#39; | &#39;partial-refresh&#39;</code></td><td>Default: <code>&#39;full&#39;</code>. Set <code>&#39;delta&#39;</code> for incremental sync (requires <code>delta</code> config; defaults apply when omitted).</td></tr><tr><td><code>delta</code></td><td><code>object</code></td><td>Delta detection — only used when <code>mode: &#39;delta&#39;</code>. See <a href="#delta"><code>delta</code></a>.</td></tr><tr><td><code>schedule</code></td><td><code>number | string | object | null</code></td><td>Internal schedule — see <a href="#schedule"><code>schedule</code></a>. Omit for manual/external runs.</td></tr><tr><td><code>viewMapping</code></td><td><code>object</code></td><td>Column/rename mapping. Inferred from the target consumption view if omitted.</td></tr><tr><td><code>refresh</code></td><td><code>&#39;full&#39; | { mode: &#39;partial&#39;, slice }</code></td><td>Query-shape rebuild strategy; <code>slice</code> is required for partial refresh.</td></tr><tr><td><code>retention</code></td><td><code>{ retentionDays?, maxRuns? }</code></td><td>Per-pipeline run-history retention (overrides the global housekeeping policy).</td></tr><tr><td><code>preload</code></td><td><code>boolean | { mode?, wait? }</code></td><td>Initial load at startup — see <a href="#preload"><code>preload</code></a>.</td></tr><tr><td><code>flags</code></td><td><code>object?</code></td><td>Advanced integration flags (e.g. entity-cache behavior for federation). Rarely set directly.</td></tr></tbody></table><h3 id="source" tabindex="-1"><code>source</code> <a class="header-anchor" href="#source" aria-label="Permalink to &quot;`source`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>service</code></td><td>—</td><td>Connected service name (<code>cds.requires</code> key).</td></tr><tr><td><code>entity</code></td><td>—</td><td>Entity-shape read. Mutually exclusive with <code>query</code>.</td></tr><tr><td><code>query</code></td><td>—</td><td>Query-shape read: a closure <code>(tracker) =&gt; SELECT …</code>.</td></tr><tr><td><code>kind</code></td><td>auto</td><td><code>&#39;cqn&#39; | &#39;odata&#39; | &#39;odata-v2&#39; | &#39;hcql&#39; | &#39;rest&#39;</code>. Usually inferred from the service.</td></tr><tr><td><code>adapter</code></td><td>—</td><td>Custom <code>BaseSourceAdapter</code> subclass — see <a href="/cds-data/pipeline/guide/sources/custom.html">Custom source adapter</a>.</td></tr><tr><td><code>origin</code></td><td>—</td><td>Multi-source fan-in label; requires the <code>sourced</code> aspect on the target. See <a href="/cds-data/pipeline/guide/recipes/multi-source.html">Multi-source fan-in</a>.</td></tr><tr><td><code>batchSize</code></td><td><code>1000</code></td><td>Rows requested per read batch.</td></tr><tr><td><code>maxRetries</code></td><td><code>3</code></td><td>Remote I/O retries.</td></tr><tr><td><code>retryDelay</code></td><td><code>1000</code></td><td>Retry backoff (ms).</td></tr><tr><td><code>delay</code></td><td><code>0</code></td><td>Inter-batch delay (ms) for throttling.</td></tr><tr><td><code>rest</code></td><td>—</td><td>REST adapter config (path, pagination, <code>dataPath</code>, …). See <a href="/cds-data/pipeline/guide/sources/rest.html">REST sources</a>.</td></tr></tbody></table><h3 id="target" tabindex="-1"><code>target</code> <a class="header-anchor" href="#target" aria-label="Permalink to &quot;`target`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>entity</code></td><td>Target entity fully-qualified name <strong>(required)</strong>.</td></tr><tr><td><code>service</code></td><td><code>&#39;db&#39;</code> or unset → local DB (<code>DbTargetAdapter</code>); a remote OData service → <code>ODataTargetAdapter</code>; anything else needs <code>adapter</code>.</td></tr><tr><td><code>kind</code></td><td>Explicit selector: <code>&#39;odata&#39; | &#39;odata-v2&#39;</code>.</td></tr><tr><td><code>adapter</code></td><td>Custom <code>BaseTargetAdapter</code> subclass — see <a href="/cds-data/pipeline/guide/targets/custom.html">Custom target adapter</a>.</td></tr><tr><td><code>batchSize</code>, <code>keyColumns</code>, <code>maxRetries</code>, <code>retryDelay</code></td><td>Write tuning (documented in <a href="/cds-data/pipeline/guide/targets/odata.html">OData targets</a>).</td></tr></tbody></table><h3 id="delta" tabindex="-1"><code>delta</code> <a class="header-anchor" href="#delta" aria-label="Permalink to &quot;`delta`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>mode</code></td><td><code>&#39;timestamp&#39;</code> when <code>mode: &#39;delta&#39;</code></td><td><code>&#39;timestamp&#39;</code>, <code>&#39;key&#39;</code>, or <code>&#39;datetime-fields&#39;</code>. Ignored unless pipeline <code>mode</code> is <code>&#39;delta&#39;</code>.</td></tr><tr><td><code>field</code></td><td><code>&#39;modifiedAt&#39;</code></td><td>Timestamp or key field carrying the high-watermark.</td></tr><tr><td><code>dateField</code>, <code>timeField</code></td><td>—</td><td>For <code>&#39;datetime-fields&#39;</code> mode (OData V2 pattern).</td></tr></tbody></table><h3 id="schedule" tabindex="-1"><code>schedule</code> <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;`schedule`&quot;">​</a></h3><p>Normalized to <code>{ every, engine }</code> or no internal schedule.</p><table tabindex="0"><thead><tr><th>Input</th><th>Result</th></tr></thead><tbody><tr><td><code>undefined</code> / <code>null</code> / <code>0</code> / <code>&#39;&#39;</code></td><td>No internal schedule — run via <code>execute</code> or the management API.</td></tr><tr><td><code>number</code> (ms)</td><td><code>{ every, engine: &#39;spawn&#39; }</code> — in-process interval.</td></tr><tr><td>time string (e.g. <code>&#39;10m&#39;</code>)</td><td><code>{ every, engine: &#39;spawn&#39; }</code>.</td></tr><tr><td>5-field cron string</td><td><code>{ every, engine: &#39;queued&#39; }</code> — cross-instance single-winner.</td></tr><tr><td><code>{ every, engine? }</code></td><td><code>engine</code> defaults to <code>&#39;queued&#39;</code> for cron, else <code>&#39;spawn&#39;</code>.</td></tr></tbody></table><p>See <a href="/cds-data/pipeline/guide/recipes/internal-scheduling-queued.html">Internal scheduling (queued)</a> and <a href="/cds-data/pipeline/guide/recipes/external-scheduling-jss.html">External scheduling (JSS)</a>.</p><h3 id="preload" tabindex="-1"><code>preload</code> <a class="header-anchor" href="#preload" aria-label="Permalink to &quot;`preload`&quot;">​</a></h3><p>Runs an initial load right after registration, so the target is not empty between boot and the first scheduled tick.</p><table tabindex="0"><thead><tr><th>Input</th><th>Behavior</th></tr></thead><tbody><tr><td>omitted / <code>false</code></td><td>No startup run.</td></tr><tr><td><code>true</code></td><td>Background initial load in the pipeline&#39;s effective mode (does not block boot).</td></tr><tr><td><code>{ mode?, wait? }</code></td><td><code>wait: true</code> blocks <code>addPipeline</code> until the load completes (a failure then fails boot). <code>mode</code> overrides the run mode for the initial load only.</td></tr></tbody></table><p>A disabled (paused) pipeline skips its preload run.</p><h2 id="running-pipelines" tabindex="-1">Running pipelines <a class="header-anchor" href="#running-pipelines" aria-label="Permalink to &quot;Running pipelines&quot;">​</a></h2><h3 id="execute-name-options" tabindex="-1"><code>execute(name, options?)</code> <a class="header-anchor" href="#execute-name-options" aria-label="Permalink to &quot;`execute(name, options?)`&quot;">​</a></h3><p>Runs a pipeline immediately.</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipelines.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NorthwindProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { mode: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;full&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// fire-and-forget:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pipelines.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execute</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NorthwindProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { async: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, engine: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;queued&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Values</th></tr></thead><tbody><tr><td><code>mode</code></td><td>pipeline default</td><td><code>&#39;full&#39;</code>, <code>&#39;delta&#39;</code>, <code>&#39;partial-refresh&#39;</code>.</td></tr><tr><td><code>trigger</code></td><td><code>&#39;manual&#39;</code></td><td><code>&#39;manual&#39;</code>, <code>&#39;scheduled&#39;</code>, <code>&#39;external&#39;</code>, <code>&#39;event&#39;</code> — recorded on the run.</td></tr><tr><td><code>async</code></td><td><code>false</code></td><td><code>true</code> returns immediately; the run continues in the background.</td></tr><tr><td><code>engine</code></td><td><code>&#39;spawn&#39;</code></td><td><code>&#39;spawn&#39;</code> or <code>&#39;queued&#39;</code> (only meaningful with <code>async: true</code>).</td></tr><tr><td><code>event</code></td><td>—</td><td>Event-driven micro-run block: <code>{ read: &#39;key&#39; | &#39;payload&#39;, action?, keys?, payload? }</code>. See <a href="/cds-data/pipeline/guide/recipes/event-driven-runs.html">Event-driven runs</a>.</td></tr><tr><td><code>tenant</code></td><td>—</td><td>Explicit tenant context.</td></tr></tbody></table><h3 id="executefortenant-tenant-name-options" tabindex="-1"><code>executeForTenant(tenant, name, options?)</code> <a class="header-anchor" href="#executefortenant-tenant-name-options" aria-label="Permalink to &quot;`executeForTenant(tenant, name, options?)`&quot;">​</a></h3><p>Runs a pipeline in a specific tenant&#39;s context. See <a href="/cds-data/federation/integration/multitenancy.html">Multi-tenancy</a>.</p><h3 id="executeevent-name-options" tabindex="-1"><code>executeEvent(name, options)</code> <a class="header-anchor" href="#executeevent-name-options" aria-label="Permalink to &quot;`executeEvent(name, options)`&quot;">​</a></h3><p>Convenience wrapper for event-driven micro-runs; requires <code>options.event.read</code>. See <a href="/cds-data/pipeline/guide/recipes/event-driven-runs.html">Event-driven runs</a>.</p><h2 id="managing-pipelines-at-runtime" tabindex="-1">Managing pipelines at runtime <a class="header-anchor" href="#managing-pipelines-at-runtime" aria-label="Permalink to &quot;Managing pipelines at runtime&quot;">​</a></h2><p>All of these persist to the tracker as <strong>overrides</strong> on top of the coded baseline — they survive restarts. See <a href="/cds-data/pipeline/guide/concepts/overrides.html">Configuration overrides</a>.</p><table tabindex="0"><thead><tr><th>Method</th><th>Purpose</th></tr></thead><tbody><tr><td><code>getStatus(name)</code></td><td>Current tracker status (<code>idle</code> / <code>running</code> / <code>failed</code>, last run, counts).</td></tr><tr><td><code>setSchedule(name, { every, cron, engine })</code></td><td>Hot-replace the schedule.</td></tr><tr><td><code>clearSchedule(name)</code></td><td>Stop the schedule (persists <code>schedule: null</code>).</td></tr><tr><td><code>isScheduleLiveChangeSupported(name)</code></td><td>Whether a queued schedule can be changed live on this runtime (CDS 10+).</td></tr><tr><td><code>setEnabled(name, enabled)</code></td><td>Pause/resume scheduled ticks. Manual <code>execute</code> still works while paused.</td></tr><tr><td><code>setOverrides(name, patch)</code></td><td>Merge and persist a runtime override patch.</td></tr><tr><td><code>clearOverrides(name, keys?)</code></td><td>Remove override keys (all, or the listed ones).</td></tr><tr><td><code>getConfigView(name)</code></td><td>Returns <code>{ base, overrides, effective }</code> for the pipeline.</td></tr><tr><td><code>clear(name)</code></td><td>Clear the target and reset the tracker watermark.</td></tr></tbody></table><h3 id="data-inspector-flow-metadata" tabindex="-1">Data inspector / flow metadata <a class="header-anchor" href="#data-inspector-flow-metadata" aria-label="Permalink to &quot;Data inspector / flow metadata&quot;">​</a></h3><p>These back the Pipeline Console; you can also call them directly.</p><table tabindex="0"><thead><tr><th>Method</th><th>Returns</th></tr></thead><tbody><tr><td><code>inspectData(name, opts?)</code></td><td>Paged source/target preview rows (JSON).</td></tr><tr><td><code>inspectCapabilities(name)</code></td><td>Which inspector sides are available.</td></tr><tr><td><code>getFlowMetadata(name, opts?)</code></td><td>Per-pipeline data-flow graph.</td></tr><tr><td><code>getLandscapeMetadata(opts?)</code></td><td>All-pipelines landscape graph.</td></tr></tbody></table><h2 id="event-hooks" tabindex="-1">Event hooks <a class="header-anchor" href="#event-hooks" aria-label="Permalink to &quot;Event hooks&quot;">​</a></h2><p>Five namespaced events bracket every run. Register handlers with the standard CAP <code>before</code> / <code>on</code> / <code>after</code> API, keyed by pipeline name.</p><div class="language-javascript vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pipelines.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">before</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PIPELINE.MAP&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NorthwindProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { … })</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pipelines.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">on</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PIPELINE.READ&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NorthwindProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { … })</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pipelines.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">after</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;PIPELINE.DONE&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;NorthwindProducts&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">req</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { … })</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><table tabindex="0"><thead><tr><th>Event</th><th>When</th><th>Cardinality</th></tr></thead><tbody><tr><td><code>PIPELINE.START</code></td><td>Before READ</td><td>Once per run</td></tr><tr><td><code>PIPELINE.READ</code></td><td>Stream setup</td><td>Once per run</td></tr><tr><td><code>PIPELINE.MAP</code></td><td>After each batch is read</td><td>Per batch</td></tr><tr><td><code>PIPELINE.WRITE</code></td><td>After each batch is mapped</td><td>Per batch</td></tr><tr><td><code>PIPELINE.DONE</code></td><td>Run finished (success or failure)</td><td>Once per run</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title"><code>on</code> replaces the default</p><p><code>on(&#39;PIPELINE.MAP&#39;, …)</code> and <code>on(&#39;PIPELINE.WRITE&#39;, …)</code> <strong>replace</strong> the built-in mapper/writer for that pipeline. To layer behavior on top of the defaults, use <code>before</code> / <code>after</code>. The <code>name</code> must match <code>addPipeline({ name })</code> (or the federated entity name for <code>@federation.replicate</code>).</p></div><p>For worked examples, see <a href="/cds-data/pipeline/guide/recipes/event-hooks.html">Event hooks</a>.</p><h2 id="plugin-configuration-cds-requires-datapipeline" tabindex="-1">Plugin configuration (<code>cds.requires.datapipeline</code>) <a class="header-anchor" href="#plugin-configuration-cds-requires-datapipeline" aria-label="Permalink to &quot;Plugin configuration (`cds.requires.datapipeline`)&quot;">​</a></h2><p>Separate from <code>addPipeline</code> — this configures the plugin itself in <code>package.json</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Purpose</th></tr></thead><tbody><tr><td><code>impl: &#39;cds-data-pipeline&#39;</code></td><td>Activates the plugin.</td></tr><tr><td><code>management.reuse.api</code></td><td>Mount the management OData service at <code>/pipeline/</code>.</td></tr><tr><td><code>management.reuse.console</code></td><td>Mount the <a href="/cds-data/pipeline/guide/pipeline-console.html">Pipeline Console</a> (implies <code>api</code>).</td></tr><tr><td><code>management.inspect: false</code></td><td>Disable the data inspector.</td></tr><tr><td><code>housekeeping.{ retentionDays, maxRuns, schedule }</code></td><td>Global <code>PipelineRuns</code> retention. See <a href="/cds-data/pipeline/guide/concepts/housekeeping.html">Housekeeping</a>.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./management-service.html">Management service</a> — the HTTP/OData equivalent of this API.</li><li><a href="./features.html">Features</a> — capability catalog.</li><li><a href="/cds-data/pipeline/guide/get-started.html">Get started</a> — end-to-end walkthrough.</li></ul>',52)])])}const k=t(s,[["render",n]]);export{u as __pageData,k as default};
